alter table public.teacher_homework_submissions add constraint teacher_homework_score_nonnegative check(score is null or score>=0);
create policy teacher_homework_submissions_insert on public.teacher_homework_submissions for insert to authenticated with check (exists(select 1 from public.teacher_homework_tasks h join public.school_memberships m on m.id=h.teacher_membership_id join public.student_enrollments e on e.student_id=teacher_homework_submissions.student_id and e.school_id=h.school_id and e.class_id=h.class_id and e.academic_year_id=(select c.academic_year_id from public.classes c where c.id=h.class_id and c.school_id=h.school_id) and e.status='enrolled' where h.id=teacher_homework_submissions.task_id and h.school_id=teacher_homework_submissions.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('teacher','class_teacher') and exists(select 1 from public.class_subjects cs where cs.school_id=h.school_id and cs.class_id=h.class_id and cs.subject_id=h.subject_id and cs.teacher_membership_id=m.id)));
create policy teacher_homework_submissions_update on public.teacher_homework_submissions for update to authenticated using (exists(select 1 from public.teacher_homework_tasks h join public.school_memberships m on m.id=h.teacher_membership_id where h.id=teacher_homework_submissions.task_id and h.school_id=teacher_homework_submissions.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('teacher','class_teacher') and exists(select 1 from public.class_subjects cs where cs.school_id=h.school_id and cs.class_id=h.class_id and cs.subject_id=h.subject_id and cs.teacher_membership_id=m.id))) with check (exists(select 1 from public.teacher_homework_tasks h join public.school_memberships m on m.id=h.teacher_membership_id where h.id=teacher_homework_submissions.task_id and h.school_id=teacher_homework_submissions.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('teacher','class_teacher') and exists(select 1 from public.class_subjects cs where cs.school_id=h.school_id and cs.class_id=h.class_id and cs.subject_id=h.subject_id and cs.teacher_membership_id=m.id) and (teacher_homework_submissions.score is null or h.max_score is null or teacher_homework_submissions.score<=h.max_score)));